+        data[i + 1] = lut[u1];
+        data[i + 2] = lut[u2];
+        data[i + 3] = lut[u3];
+        data[i + 4] = lut[u4];
+        data[i + 5] = lut[u5];
+        data[i + 6] = lut[u6];
+        data[i + 7] = lut[u7];
+      }
