+          float32x4_t vx_hi = vcvt_f32_f16(vget_high_f16(vx));
+          float32x4_t v_add_hi = vaddq_f32(vx_hi, v_three);
+          float32x4_t v_relu6_hi =
+            vminq_f32(vmaxq_f32(v_add_hi, v_zero), v_six);
+          float32x4_t vres_hi =
