+      store4(m + 0, j, fA0);
+      store4(m + 1, j, fA1);
+      store4(m + 2, j, fA2);
+      store4(m + 3, j, fA3);
+      store4(m + 4, j, fB0);
+      store4(m + 5, j, fB1);
+      store4(m + 6, j, fB2);
+      store4(m + 7, j, fB3);
+    }
